div.data-mendix-props:
"contenttype":"jsjQuery","contents":"setTimeout(() => {
 const chooseFileButton = document.getElementsByClassName("mx-fileinput-upload-button")[0];
 chooseFileButton.innerHTML = "Choose File";
 chooseFileButton.setAttribute("tabindex", -1);

 chooseFileButton.addEventListener("focus", (evt) => {
 chooseFileButton.blur();
 });

 const fileNameInput = document.querySelector(".mx-compound-control .form-control");

fileNameInput.value="";
fileNameInput.setAttribute("tabindex", -1);

 document.clickListener = document.querySelector(".mx-compound-control").addEventListener("click", (event) => {
 if (!event.target.classList.contains('mx-fileinput-upload-button')) {
 chooseFileButton.click();
 }
 });

 const parentControl = document.querySelector(".layout-upload-container");

 function handleEnterKey(event) {
 if (event.key === 'Enter') {
 chooseFileButton.click();
 }
 }

 parentControl.addEventListener('keydown', handleEnterKey);
}, 100);","contentsPath":"","onclickmf":"","documentation":"","refreshOnContextChange":true,"refreshOnContextUpdate":false,"encloseHTMLWithDiv":true
